// node/compat.json (generated by tests/compat/node.ts): which exports of Node's built-in modules
// visaljs implements, stubs or lacks, read at build time so the Node API page follows the project.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

export type Status = "complete" | "partial" | "stub" | "missing";

export interface ModuleCoverage {
  status: Status;
  implemented: string[];
  stubbed: string[];
  missing: string[];
  extra?: string[];
  notes?: string;
}

export interface Compat {
  node: string;
  summary: {
    modules: Record<Status, number> & { total: number };
    exports: { implemented: number; stubbed: number; missing: number; total: number };
  };
  modules: Record<string, ModuleCoverage>;
}

export function nodeCompat(): Compat {
  /* from web/, where astro runs (as lib/progress.ts) */
  return JSON.parse(readFileSync(resolve(process.cwd(), "../node/compat.json"), "utf8")) as Compat;
}
